-- ---------------------------------------------------------------------------
-- Lecture scheduled end time (see docs/lecture-end-date.md).
--
-- Additive only: one nullable column and one CHECK constraint. No existing
-- row is changed: every existing lecture keeps "endDate" = NULL (no backfill,
-- in particular none from ClassSchedule). "endDate" is a real UTC instant
-- written by the application, like "date"; it has no database default.
--
-- The part marked MANUAL is not generated by Prisma (Prisma 5.22 cannot
-- express CHECK constraints and ignores them, so it never reports them as
-- drift). Guarded by tests/lectures/lecture-end-date-migration-guard.test.cjs.
-- ---------------------------------------------------------------------------

-- AlterTable
ALTER TABLE "Lecture" ADD COLUMN     "endDate" TIMESTAMP(3);

-- MANUAL: an end time is always strictly after the start. (The 12-hour
-- maximum is an application rule only: lib/lecture-schedule.ts.)
ALTER TABLE "Lecture" ADD CONSTRAINT "Lecture_endDate_after_date"
  CHECK ("endDate" IS NULL OR "endDate" > "date");
